<template>
  <div id="app">
    <prism-editor
      class="special-rules-editor"
      v-model="value"
      :highlight="highlighter"
      line-numbers
      :tabSize="4"
    ></prism-editor>
  </div>
</template>

<script>
import { defineComponent, ref } from 'vue';
// import Prism Editor
import { PrismEditor } from 'vue-prism-editor';
import 'vue-prism-editor/dist/prismeditor.min.css'; // import the styles somewhere

// import highlighting library (you can use any library you want just return html string)
import { highlight, languages } from 'src/utils/prism';

// beautify format code
import beautify from 'js-beautify';

export default defineComponent({
  el: '#app',
  mixins: [],
  props: {
    editorValue: {
      type: String,
      required: true,
    },
    formatCode: {
      type: Boolean,
      required: true,
    },
  },
  components: {
    PrismEditor,
  },
  data() {
    return {
      value: this.editorValue,
    };
  },
  setup() {
    return {
      formatOptions: {
        indent_size: 4,
        indent_char: ' ',
        eol: '\n',
        end_with_newline: false,
        preserve_newlines: true,
        max_preserve_newlines: 2,
        indent_inner_html: true,
        wrap_line_length: 0,
        unformatted: [],
        extra_liners: [],
        skipNext: false,
      },
    };
  },
  watch: {
    editorValue(newValue) {
      this.value = newValue;
    },
    value(newValue) {
      if (this.skipNext) {
        this.skipNext = false;
        return;
      }
      // Only process if the new value is different
      if (newValue === this.lastValue) return;

      const processed = this.scopeHtmlFromEditor(newValue);
      this.lastValue = processed;

      this.skipNext = true;
      this.$emit('updated-value', processed);
    },
    formatCode(value) {
      if (value) {
        this.formatHtmlCode();
      }
    },
  },
  methods: {
    formatHtmlCode() {
      try {
        this.value = beautify.html(this.value, {
          ...this.formatOptions,
        });
        this.$emit('formatComplete', false);
      } catch (err) {
        logError('Error formatting HTML code:', err);
      }
    },
    highlighter(code) {
       
      return highlight(code, languages.markup, 'markup');
    },
    scopeHtmlFromEditor(html, scopeClass = 'email-template-container') {
      var className = String(scopeClass);
      var htmlContent = String(html);

      // Regex to check if already wrapped
      var wrapperRegex = new RegExp('^<div class=["\']' + className + '["\']>');
      var wrapped = htmlContent;

      // Wrap content in a container if not already wrapped
      if (!wrapperRegex.test(htmlContent.trim())) {
        wrapped = '<div class="' + className + '">' + htmlContent + '</div>';
      }

      // Rewrite style selectors with the class and handle separators
      wrapped = wrapped.replace(
        /<style[^>]*>([\s\S]*?)<\/style>/gi,
        function (match, css) {
          const scopedCss = css.replace(
            /(^|})([^{}]+)/g,
            function (m, brace, selectors) {
              const selectorList = selectors.split(',');
              const scopedSelectors = [];

              selectorList.forEach(function (s) {
                const trimmed = s.trim();
                // Avoid double-scoping
                if (
                  trimmed.startsWith('.' + scopeClass + ' ') ||
                  trimmed === '.' + scopeClass
                ) {
                  scopedSelectors.push(trimmed);
                } else {
                  scopedSelectors.push('.' + scopeClass + ' ' + trimmed);
                }
              });

              return brace + ' ' + scopedSelectors.join(', ');
            },
          );

          return '<style>' + scopedCss + '</style>';
        },
      );
       
      return wrapped;
    },
  },
});
</script>

