<template>
  <template v-if="filteredDataKey.length">
    <div
      :class="[
        'floating-menu back-white',
        popupType == 'subject'
          ? 'floating-menu-subject'
          : 'floating-menu-message',
      ]"
    >
      <q-list dense>
        <q-item
          v-for="data in filteredDataKey"
          :key="data.index"
          clickable
          @click.stop="insertKey(data.key, data.name)"
        >
          <!-- Left side -->
          <q-item-section>
            <q-item-label>{{ data.name }}</q-item-label>
          </q-item-section>

          <!-- Right side -->
          <q-item-section side>
            <q-item-label caption>{{ data.key }}</q-item-label>
          </q-item-section>
        </q-item>
      </q-list>
    </div>
  </template>
  <template v-else>
    <div
      :class="[
        'floating-menu back-white',
        popupType == 'subject'
          ? 'floating-menu-subject'
          : 'floating-menu-message',
      ]"
    >
      <q-list>
        <q-item>
          <q-item-section> No properties available </q-item-section>
        </q-item>
      </q-list>
    </div>
  </template>
</template>

<script lang="ts">
import { defineComponent, ref, PropType } from 'vue';

export interface DataKeyItem {
  index: number;
  key: string;
  name: string;
}

export default defineComponent({
  el: '#app',
  components: {},
  props: {
    editorRef: {},
    filteredDataKey: {
      type: Array as PropType<DataKeyItem[]>,
      default: () => [],
    },
    popupType: {
      type: String,
    },
  },
  data() {
    return {
      //insertedKeys : [] as string[]
    };
  },
  methods: {
    insertKey(key: string, name: string) {
      //built in function from quasar to insert text
      (this.editorRef as any)?.runCmd('insertHTML', `{{${key}}}`);

      this.$emit('update-inserted-keys', key, name);
    },
  },
  setup() {
    return {};
  },
});
</script>
<style scoped>
.floating-menu {
  position: absolute; /* or fixed if you want it relative to viewport */
  background: white;
  border: 1px solid #ccc;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.2);
  z-index: 9999;
  width: 250px; /* optional width */
  max-height: 300px; /* optional scroll */
  overflow-y: auto;
}

.floating-menu-subject {
  top: 42px;
  right: 0;
}

.floating-menu-message {
  top: 42px;
  right: 0;
}
</style>
